    pid_t pid;
    pid = fork();
    if( pid < 0 ) {
        for(i=0; i<n; i++) v+=(i+1);
        printf("c = %d ", v);
    } else if( pid == 0 ) {
        for(i=0; i<n; i++) v*=(i+1);
